@startuml

class Customer {
  + Name : string
  + Address : string
  + AccountNumber : string
}

class Broker {
  + BrokerId : int
  + Name : string
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + BillingFrequency : string
}

class InsuranceProduct {
  + ProductId : int
  + Description : string
  + Price : double
}

class Offer {
  + OfferId : int
  + ExpiryDate : date
  + Status : string
}

class ClaimCase {
  + CaseId : int
  + Description : string
  + Status : string
}

class EstimatorReport {
  + ReportId : int
  + ReportDate : date
  + Findings : string
}

class CompensationDecision {
  + DecisionId : int
  + TotalAmount : double
  + EligibleCosts : double
}

class Invoice {
  + InvoiceNumber : int
  + Amount : double
  + DueDate : date
}

class Payment {
  + PaymentId : int
  + Amount : double
  + PaymentDate : date
}

Customer "1" -- "0..*" Contract
Broker "1" -- "0..*" Customer : manages
Contract "*" -- "1" Customer
Contract "1" -- "1" InsuranceProduct
Offer "0..*" -- "1" Customer
Offer "0..*" -- "1" InsuranceProduct
Contract "1" -- "0..*" Invoice
Customer "1" -- "0..*" Payment
Customer "1" -- "0..*" ClaimCase
ClaimCase "1" -- "1..*" EstimatorReport
EstimatorReport "1" -- "0..1" CompensationDecision
CompensationDecision "1" -- "1" ClaimCase
CompensationDecision "1" -- "1" Payment

@enduml

